#!/usr/bin/env bash
set -Eeuo pipefail

STAGE_VERSION="rnatr_ssot_checkpoint_performance_phase_started_v0.1.0"
PROJECT_ROOT="/mnt/intelssd/rnatr_project"
SSOT_CLI="$PROJECT_ROOT/metadata/ssot/rnatr_ssot.py"
SSOT_DB="$PROJECT_ROOT/metadata/ssot/rnatr_ssot.sqlite"
FREEZE_QC="$PROJECT_ROOT/qc/12_general_repeat_caller_freeze/v0.4.0/general_repeat_caller_freeze.qc.tsv"
FREEZE_MANIFEST="$PROJECT_ROOT/metadata/general_caller/general_repeat_caller_freeze_v0.4.0.tsv"
SCRIPT_INSTALL="$PROJECT_ROOT/scripts/00c_checkpoint_ssot_performance_phase_started_v0.1.0.sh"

for p in "$SSOT_CLI" "$SSOT_DB" "$FREEZE_QC" "$FREEZE_MANIFEST"; do
  [[ -s "$p" ]] || { echo "ERROR: required input missing: $p" >&2; exit 2; }
done

freeze_status="$(awk -F '\t' '$1=="audit_status"{print $2}' "$FREEZE_QC" | tr -d '\015' | tail -n1)"
[[ "$freeze_status" == "PASS" ]] || {
  echo "ERROR: Stage 12G freeze is not PASS: $freeze_status" >&2
  exit 2
}

SELF="$(readlink -f "$0")"
if [[ "$SELF" != "$SCRIPT_INSTALL" && ! -e "$SCRIPT_INSTALL" ]]; then
  cp "$SELF" "$SCRIPT_INSTALL.part"
  chmod 0755 "$SCRIPT_INSTALL.part"
  mv "$SCRIPT_INSTALL.part" "$SCRIPT_INSTALL"
fi

CLI_BAK="$SSOT_CLI.pre_perf_checkpoint.$(date +%Y%m%d_%H%M%S).bak"
DB_BAK="$SSOT_DB.pre_perf_checkpoint.$(date +%Y%m%d_%H%M%S).bak"
cp -a "$SSOT_CLI" "$CLI_BAK"
cp -a "$SSOT_DB" "$DB_BAK"

restore_all() {
  rc=$?
  echo "ERROR: SSOT checkpoint update failed; restoring source and database" >&2
  cp -a "$CLI_BAK" "$SSOT_CLI"
  cp -a "$DB_BAK" "$SSOT_DB"
  exit "$rc"
}
trap restore_all ERR

PATCH_TMP="$(mktemp)"
printf '%s' '' | base64 -d > "$PATCH_TMP"
python -m py_compile "$PATCH_TMP"
python "$PATCH_TMP" "$SSOT_CLI"
rm -f "$PATCH_TMP"

echo "===== REBUILD SSOT CHECKPOINT ====="
python "$SSOT_CLI" --project-root "$PROJECT_ROOT" rebuild

echo
echo "===== VALIDATE ====="
python "$SSOT_CLI" --project-root "$PROJECT_ROOT" validate

trap - ERR

echo
echo "===== CHECKPOINT STATE ====="
python "$SSOT_CLI" --project-root "$PROJECT_ROOT" query   "SELECT decision_key,statement,status FROM current_decisions WHERE decision_key='performance_profiling_phase_started'"

python "$SSOT_CLI" --project-root "$PROJECT_ROOT" query   "SELECT question_key,priority,status,blocking,next_action FROM current_open_questions WHERE question_key='PERFORMANCE_OPTIMIZATION_11F_11H'"

echo
echo "SSOT_PERFORMANCE_CHECKPOINT_PASS"
